-- Two convention versions of the live engine, so the paper fund runs before the protocol's
-- measurement is complete: the owner's decision of 2026-09-22 00:48 PT ("I want this to go live").
--
-- Every one of the four numbers the protocol measures is here a CONVENTION the owner chose, and
-- each field says so (params.basis = "convention", every provenance kind "convention" or "fact",
-- the name carries "(conventions)"). engine.Params.Validate accepts such a version only under
-- that label and never as a measured one. Scalper v3 and Value v3 stay free for the measured
-- result of docs/v3-measurement-protocol.md; these are separate trials, and the registry's count
-- moves from 18 to 20 for both.
--
-- As draft. A person sets probation from the buckets page; the engine then seeds a $1,000 bucket
-- and trades on its next look. Generated from the engine's own constructors (ConventionScalper,
-- ConventionValue), so the stored params are exactly what the engine accepts.

with family (name, blurb, parent, params) as (values
    ('Scalper (conventions)', 'Trades often, banks small gains; fills only what the book displayed; the four numbers are the owner''s conventions, not the protocol''s measurement', 'Scalper', '{"name":"Scalper (conventions)","blurb":"Trades often, banks small gains; fills only what the book displayed; the four numbers are the owner''s conventions, not the protocol''s measurement","basis":"convention","lambda":0.5,"stale_cost":0.0012,"stale_cost_sell":0.0012,"drift_tol":0,"kappa":0.25,"window_cap_bps":2500,"seed_cents":100000,"exhausted_cents":100,"tau_min":25,"tau_max":900,"band_min":0.05,"band_max":0.95,"max_bets":25,"min_gap":8,"min_hold":5,"min_tau":8,"exit":"ev","take_capture":0.8,"levels":5,"fee_per_fill":false,"provenance":{"band_max":{"kind":"inherited","value":0.95,"note":"unmeasured; taken unchanged from the parent v2 so that parent and child differ only in fills, sizing and belief"},"band_min":{"kind":"inherited","value":0.05,"note":"unmeasured; taken unchanged from the parent v2 so that parent and child differ only in fills, sizing and belief"},"drift_tol":{"kind":"fact","value":0,"note":"no reference engine runs beside the third; the drift gate is open and the number decides nothing"},"exhausted_cents":{"kind":"inherited","value":100,"note":"v2''s BankruptAt"},"kappa":{"kind":"convention","value":0.25,"note":"quarter Kelly: a risk preference, not measurable"},"lambda":{"kind":"convention","value":0.5,"note":"the owner''s convention, 2026-09-22: half the model''s disagreement with the market, chosen to run the fund before the protocol''s measurement completes (TRAIN closes about 2026-09-27); the measured lambda belongs to Scalper v3 and Value v3, separate trials"},"levels":{"kind":"fact","value":5,"note":"a snapshot records five bid levels per side"},"max_bets":{"kind":"inherited","value":25,"note":"unmeasured; taken unchanged from Scalper v2; counts buy orders with a fill"},"min_gap":{"kind":"inherited","value":8,"note":"unmeasured; taken unchanged from Scalper v2"},"min_hold":{"kind":"inherited","value":5,"note":"unmeasured; taken unchanged from Scalper v2"},"min_tau":{"kind":"inherited","value":8,"note":"unmeasured; taken unchanged from the parent v2 so that parent and child differ only in fills, sizing and belief"},"seed_cents":{"kind":"convention","value":100000,"note":"the same $1,000 as v2, so the lines compare"},"stale_cost":{"kind":"convention","value":0.0012,"note":"the owner''s convention, 2026-09-22: the M2 proxy''s mean on the 10 TRAIN windows complete at 07:10 UTC, rounded; not a frozen measurement"},"stale_cost_sell":{"kind":"convention","value":0.0012,"note":"the owner''s convention, 2026-09-22: the M2s proxy''s mean on the same 10 windows, rounded; not a frozen measurement"},"take_capture":{"kind":"inherited","value":0.8,"note":"unmeasured; taken unchanged from Scalper v2; the review found its effect unresolved"},"tau_max":{"kind":"inherited","value":900,"note":"unmeasured; taken unchanged from the parent v2 so that parent and child differ only in fills, sizing and belief"},"tau_min":{"kind":"inherited","value":25,"note":"unmeasured; taken unchanged from Scalper v2"},"window_cap_bps":{"kind":"limit","value":2500,"note":"the owner''s limit; v2''s TotalCap, on min(E_w, seed)"}},"protocol_sha":"","result_sha":""}'::jsonb),
    ('Value (conventions)', 'Model and market blended at the owner''s weight; holds to settlement; the four numbers are the owner''s conventions, not the protocol''s measurement', 'Value', '{"name":"Value (conventions)","blurb":"Model and market blended at the owner''s weight; holds to settlement; the four numbers are the owner''s conventions, not the protocol''s measurement","basis":"convention","lambda":0.5,"stale_cost":0.0012,"stale_cost_sell":0,"drift_tol":0,"kappa":0.25,"window_cap_bps":2500,"seed_cents":100000,"exhausted_cents":100,"tau_min":8,"tau_max":900,"band_min":0.05,"band_max":0.95,"max_bets":1,"min_gap":20,"min_hold":0,"min_tau":8,"exit":"hold","take_capture":0,"levels":5,"fee_per_fill":false,"provenance":{"band_max":{"kind":"inherited","value":0.95,"note":"unmeasured; taken unchanged from the parent v2 so that parent and child differ only in fills, sizing and belief"},"band_min":{"kind":"inherited","value":0.05,"note":"unmeasured; taken unchanged from the parent v2 so that parent and child differ only in fills, sizing and belief"},"drift_tol":{"kind":"fact","value":0,"note":"no reference engine runs beside the third; the drift gate is open and the number decides nothing"},"exhausted_cents":{"kind":"inherited","value":100,"note":"v2''s BankruptAt"},"kappa":{"kind":"convention","value":0.25,"note":"quarter Kelly: a risk preference, not measurable"},"lambda":{"kind":"convention","value":0.5,"note":"the owner''s convention, 2026-09-22: half the model''s disagreement with the market, chosen to run the fund before the protocol''s measurement completes (TRAIN closes about 2026-09-27); the measured lambda belongs to Scalper v3 and Value v3, separate trials"},"levels":{"kind":"fact","value":5,"note":"a snapshot records five bid levels per side"},"max_bets":{"kind":"inherited","value":1,"note":"unmeasured; taken unchanged from Value v2; counts buy orders with a fill"},"min_gap":{"kind":"inherited","value":20,"note":"unmeasured; taken unchanged from Value v2"},"