), s as (
    insert into strategy (family, name, description)
    select 'kalshi15m', name, blurb from family
    on conflict (family, name) do update set description = strategy.description
    returning id, name
)
insert into strategy_version (strategy_id, version, params, code_ref, hypothesis, parent_version_id, created_by, status)
select s.id, 3, f.params,
       'service/internal/engine at the release that carries migration 0020',
       f.name || ': the parent''s rules over the honest-fills engine (integer cents, paper fills from the displayed book) with the four protocol numbers CHOSEN by the owner on 2026-09-22, not measured: lambda 0.5, stale_cost 0.0012, stale_cost_sell 0.0012 for the one that sells early, drift_tol 0 (the gate is open). Registered so the paper fund runs while the protocol''s TRAIN completes; judged live at the corrected threshold like every trial. The measured versions are separate rows.',
       (select v.id from strategy_version v join strategy p on p.id = v.strategy_id where p.family = 'kalshi15m' and p.name = f.parent and v.version = 2),
       (select id from actor where handle = 'brad'),
       'draft'
  from family f join s on s.name = f.name
on conflict (strategy_id, version) do nothing;
